country_event = { # Vassal Version
	id = origin.5735
	title = origin.5735.title
	desc = origin.5735.desc
	picture = GFX_evt_burning_settlement
	show_sound = event_collapsing_ruins
	is_triggered_only = yes

	trigger = {
		has_origin = origin_imperial_vassal
	}

	# "Free once more"
	option = {
		name = origin.5735.a
		trigger = {
			OR = {
				is_ai = no
				is_militarist = no
				is_xenophobe = no
			}
		}
		custom_tooltip = SET_SUBJECT_OF_EFFECT_NONE_WE_VERBOSE
		hidden_effect = {
			set_subject_of = { who = none }
		}
	}
	# Take leadership
	option = {
		name = origin.5735.b
		trigger = {
			OR = {
				is_ai = no
				is_militarist = yes
				is_xenophobe = yes
			}
		}
		add_resource = { influence = -100 }
		custom_tooltip = SET_SUBJECT_OF_EFFECT_NONE_WE_VERBOSE
		custom_tooltip = origin.5735.b.tt
		hidden_effect = {
			set_subject_of = { who = none }
			every_playable_country = {
				limit = {
					OR = {
						has_country_flag = origin_imperial_vassal_ex_overlord@event_target:previous_overlord
						has_origin = origin_imperial_vassal
					}
					NOT = { is_same_value = root }
				}
				root = {
					if = {
						limit = {
							NOT = {
								has_casus_belli = {
									target = prev
									type = cb_subjugation
								}
							}
						}
						add_casus_belli = {
							type = cb_subjugation
							who = prev
							days = 10800
						}
					}
				}
			}
		}
	}
	# "We remain loyal"
	option = {
		name = origin.5735.c
		trigger = {
			is_ai = no
			NOT = {
				is_at_war_with = event_target:previous_overlord
			}
		}
		custom_tooltip = origin.5735.c.tt
		add_resource = { influence = 100 }
	}

	after = {
		if = {
			limit = {
				is_ai = yes
				NOT = { has_country_flag = origin_imperial_vassal_rival_country }
			}
			country_event = {
				id = origin.5740
				days = 15
				random = 45
			}
		}
	}
}

