country_event = {
	id = origin.6253
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		capital_scope = {
			export_trigger_value_to_variable = {
				trigger = pop_amount
				variable = seperatist_pops
			}
			change_variable = { #Makes it so that they are at least always 500 pops behind the player
				which = seperatist_pops
				value = 500
			}
		}
		home_planet = {
			export_trigger_value_to_variable = {
				trigger = pop_amount
				variable = fotd_pops
			}
		}
		if = {
			limit = {
				check_variable_arithmetic = {
					which = capital_scope.seperatist_pops
					value < home_planet.fotd_pops
				}
			}
			capital_scope = {
				create_pop_group = {
					species = root.species
				}
				set_timed_carrier_flag = {
					flag = ignore_ai_building_limitations
					days = 1
				}
				if = {
					limit = {
						NOT = { is_variable_set = added_pops }
					}
					set_variable = {
						which = added_pops
						value = 1
					}
				}
				else = {
					change_variable = {
						which = added_pops
						value = 1
					}
				}
				if = { #every 3 pops we try to add a building or district
					limit = {
						check_variable = {
							which = added_pops
							value >= 3
						}
					}
					if = {
						limit = {
							free_building_slots > 0
						}
						random_list = {
							1 = {
								modifier = {
									factor = 0
									has_building = building_foundry_1
								}
								add_building = building_foundry_1
							}
							1 = {
								modifier = {
									factor = 0
									has_building = building_factory_1
								}
								add_building = building_factory_1
							}
							1 = {
								modifier = {
									factor = 0
									has_building = building_medical_2
								}
								add_building = building_foundry_1
							}
							5 = {
								modifier = {
									factor = 0
									has_building = building_refinery
								}
								add_building = building_refinery
							}
							1 = {
								add_building = building_research_lab_1
							}
						}
					}
					else_if = {
						limit = {
							free_district_slots > 0
						}
						random_list = {
							2 = {
								add_district = district_city
							}
							1 = {
								modifier = {
									factor = 0
									num_free_districts = {
										type = district_farming
										value = 0
									}
								}
								modifier = {
									factor = 0
									owner = {
										is_lithoid_empire = yes
									}
								}
								add_district = district_farming
							}
							1 = {
								modifier = {
									factor = 0
									num_free_districts = {
										type = district_mining
										value = 0
									}
								}
								modifier = {
									factor = 0
									from = {
										is_catalytic_empire = yes
									}
								}
								add_district = district_mining
							}
							1 = {
								modifier = {
									factor = 0
									num_free_districts = {
										type = district_generator
										value = 0
									}
								}
								add_district = district_generator
							}
						}
					}
					else_if = {
						limit = {
							count_deposits = {
								category = deposit_cat_blockers_natural
								count > 0
							}
						}
						clear_blockers = yes
					}
					set_variable = { #reset the counter to 0
						which = added_pops
						value = 0
					}
				}
			}
		}
		capital_scope = { clear_variable = seperatist_pops }
		from.home_planet = { clear_variable = fotd_pops }
	}
}

